import{a}from"./chunk-SFQL27JW.js";import"./chunk-2K42ZOD6.js";a();var o=JSON.parse('{"help.sec_start":"Primeiros passos","help.sec_mark":"Corrigir um trabalho","help.sec_score":"Notas e rubricas","help.sec_back":"Devolver os trabalhos","help.sec_class":"Turmas e notas","help.sec_safe":"Salvamento e seguran\xE7a","help.sec_plan":"Planejar e ensinar","help.sec_private":"Privacidade","help.open_work_q":"Como abro um lote de trabalhos?","help.open_work_a1":"Baixe as entregas da turma do sistema da sua escola como ZIP, depois abra a atividade na Linha do curso da turma e clique em **Trazer trabalhos**, ou solte o ZIP sobre ela. Uma pasta, PDFs soltos, arquivos do Word e fotos funcionam do mesmo jeito.","help.open_work_a2":"**Trazer trabalhos** tamb\xE9m abre uma pasta, uma digitaliza\xE7\xE3o da turma inteira ou arquivos para associar a uma lista.","help.open_work_a3":"Os trabalhos ficam guardados neste navegador, ent\xE3o o lote espera por voc\xEA no In\xEDcio e em Pend\xEAncias na pr\xF3xima vez que voc\xEA abrir o aplicativo.","help.open_work_w":"come\xE7ar importar enviar zip download entregas soltar pasta","help.open_work_go":"Ir para o In\xEDcio","help.try_sample_q":"Posso experimentar sem trabalhos reais?","help.try_sample_a1":"Sim. **Experimentar a turma de exemplo**, em Configura\xE7\xF5es, Exibi\xE7\xE3o, abre duas turmas inventadas no meio de um per\xEDodo, com trabalhos corrigidos, um di\xE1rio de notas, um hor\xE1rio e aulas. Digite “exemplo” em Buscar para chegar l\xE1.","help.try_sample_a2":"O exemplo fica separado do seu pr\xF3prio trabalho. **Sair do exemplo**, em Configura\xE7\xF5es, Exibi\xE7\xE3o, apaga tudo com um clique, e o seu trabalho fica como voc\xEA deixou.","help.try_sample_w":"demo exemplo pr\xE1tica teste inventado","help.find_anything_q":"O que \xE9 o Buscar?","help.find_anything_a1":"Uma \xFAnica caixa que alcan\xE7a cada aluno, atividade, ferramenta, configura\xE7\xE3o e resposta de ajuda. Abra-a no alto da barra lateral ou pressione **Ctrl K** (**⌘K** em um Mac).","help.find_anything_a2":"Digite algumas letras do que procura, mova-se com as setas e pressione Enter. Cada linha faz o mesmo que seu bot\xE3o.","help.find_anything_w":"buscar procurar encontrar paleta ctrl k atalho","help.full_screen_q":"O aplicativo pode ocupar a tela inteira?","help.full_screen_a1":"Sim. Pressione **F** ou ative **Tela cheia** em Configura\xE7\xF5es, Exibi\xE7\xE3o. Com um trabalho aberto, o bot\xE3o fica na barra superior, ao lado do ✕. As barras do navegador somem e a barra lateral vira s\xF3 \xEDcones. Na tela de corre\xE7\xE3o a barra lateral tamb\xE9m some, para o trabalho ter espa\xE7o.","help.full_screen_a2":"Pressione **F** de novo, o mesmo bot\xE3o ou **Esc** para sair. Nada \xE9 fechado nem perdido ao entrar ou sair. Em trabalhos formativos o F \xE9 para coment\xE1rios, ent\xE3o use o bot\xE3o ali. Aulas e Apresentar funcionam do mesmo jeito.","help.full_screen_a3":"A lista de alunos tamb\xE9m se oculta: deixe o ponteiro na borda esquerda da tela, ou pressione **[**, e ela volta. Em **Configura\xE7\xF5es, Corre\xE7\xE3o** voc\xEA pode mant\xEA-la vis\xEDvel ou ocultar tamb\xE9m as ferramentas.","help.full_screen_w":"tela cheia maximizar maior espa\xE7o foco","help.add_class_q":"Como adiciono uma turma e sua lista?","help.add_class_a1":"1. Clique em **Adicionar uma turma** na barra lateral e d\xEA um nome a ela.","help.add_class_a2":"2. Cole os nomes dos alunos, um por linha. Eles ficam na ordem em que voc\xEA cola.","help.add_class_a3":"3. Abra a aba **Pessoas** da turma para adicionar um ID, um e-mail ou uma nota para cada aluno.","help.add_class_a4":"Com uma lista, ao abrir os trabalhos dessa turma aparece cada aluno, inclusive quem n\xE3o entregou nada.","help.add_class_w":"lista alunos estudantes nomes nova turma","help.todo_q":"Como funciona a lista de pend\xEAncias?","help.todo_a1":"**Pend\xEAncias**, na barra lateral, \xE9 uma lista s\xF3. Suas pr\xF3prias pend\xEAncias t\xEAm um c\xEDrculo cont\xEDnuo. As linhas com c\xEDrculo tracejado s\xE3o coisas que o aplicativo notou no seu trabalho salvo: trabalhos para corrigir, trabalhos para devolver, uma turma sem aula planejada, trabalhos n\xE3o entregues para cobrar.","help.todo_a2":"Escreva uma pend\xEAncia do jeito que voc\xEA falaria e pressione Enter. Por enquanto os dias s\xE3o lidos em ingl\xEAs: um dia no fim (“tomorrow”, “friday”, “nov 20”), o nome de uma turma ou de um aluno \xE9 reconhecido sozinho, e um clique no que foi reconhecido o remove. Pressione **N** em qualquer lugar fora de um trabalho para adicionar uma.","help.todo_a3":"Clique em uma linha para dar a ela um dia, uma turma, algo a que ela se refere, uma repeti\xE7\xE3o ou uma nota. As linhas do aplicativo somem sozinhas quando o trabalho \xE9 feito. Voc\xEA pode mover uma para outro dia, ocult\xE1-la ou desligar um tipo inteiro. **Pessoas** liga algu\xE9m da sua p\xE1gina School, com um link Email quando o endere\xE7o est\xE1 guardado.","help.todo_a4":"O **In\xEDcio** mostra as suas pr\xF3prias pend\xEAncias atrasadas ou que vencem hoje. A lista \xE9 salva com o seu trabalho de corre\xE7\xE3o, nunca na sua pasta do Planejador.","help.todo_w":"pend\xEAncias tarefas lista lembrete lembrar afazeres todo to-do","help.todo_go":"A","help.todo_week_q":"Posso ver minhas pend\xEAncias por semana?","help.todo_week_a1":"Sim. Em **Pend\xEAncias**, escolha **Semana** no canto superior direito, ou abra Calend\xE1rio, **Por hor\xE1rio**. As mesmas linhas ficam nos dias a que pertencem, com uma coluna Depois para o resto.","help.todo_week_a2":"Escreva em um dia para adicionar uma pend\xEAncia para ele, e arraste uma linha para outro dia. O que n\xE3o \xE9 feito no dia passa sozinho para hoje, e diz de que dia era.","help.todo_week_w":"pend\xEAncias semana semanal calend\xE1rio dias arrastar mover","help.todo_week_go":"A","help.focus_q":"Existe um cron\xF4metro para corrigir em sess\xF5es curtas?","help.focus_a1":"Sim. **Foco** em Pend\xEAncias, o bot\xE3o de foco no In\xEDcio ou **Focar nisto** numa pend\xEAncia ou aula come\xE7am uma sess\xE3o com um toque. Escolha no que trabalhar: um lote de trabalhos esperando corre\xE7\xE3o, uma aula ou uma das suas pend\xEAncias. Um lote de trabalhos abre no pr\xF3ximo trabalho sem nota. O cron\xF4metro fica no canto inferior esquerdo de todas as telas. Quando o tempo acaba, toca um sinal suave e voc\xEA pode fazer uma pausa, continuar ou parar.","help.focus_a2":"Defina uma meta di\xE1ria em trabalhos ou minutos em **Configura\xE7\xF5es, Foco e metas**. Um trabalho conta quando a nota est\xE1 conclu\xEDda, onde quer que voc\xEA fa\xE7a isso. Pend\xEAncias, In\xEDcio e o cron\xF4metro mostram quanto j\xE1 foi e ficam verdes quando voc\xEA chega l\xE1. A dura\xE7\xE3o de uma sess\xE3o e de uma pausa, e o sinal, tamb\xE9m s\xE3o definidos ali.","help.focus_w":"foco cron\xF4metro pomodoro sess\xE3o pausa meta di\xE1ria trabalhos minutos concentra\xE7\xE3o motiva\xE7\xE3o procrastina\xE7\xE3o","help.focus_go":"A","help.time_tracker_q":"Posso ver quanto tempo passo corrigindo e planejando?","help.time_tracker_a1":"Sim, no **Registro de tempo**, a partir de **Tempo nesta semana** em Pend\xEAncias, ou de Buscar. O tempo de corre\xE7\xE3o conta enquanto a tela de corre\xE7\xE3o est\xE1 na frente. O tempo de planejamento conta numa sess\xE3o de foco numa aula, e depois de alguns minutos de trabalho cont\xEDnuo em aulas, no Calend\xE1rio ou numa Linha do curso, mas n\xE3o enquanto voc\xEA apresenta nem durante as suas aulas. A contagem para depois de alguns minutos sem atividade.","help.time_tracker_a2":"O registro mostra uma semana, um m\xEAs ou tr\xEAs meses: totais, uma barra por dia, corre\xE7\xE3o por atividade e planejamento por aula. Use **Adicionar tempo** para trabalho feito fora do aplicativo. **Baixar como planilha** salva tudo como arquivo CSV. Em **Configura\xE7\xF5es, Foco e metas** voc\xEA define quando a contagem para e depois de quanto tempo o planejamento conta.","help.time_tracker_w":"tempo registro horas minutos quanto corrigir planejar carga trabalho planilha csv","help.time_tracker_go":"Abrir o registro de tempo","help.plan_grading_q":"O app pode me dizer quanto tempo vou levar para corrigir?","help.plan_grading_a1":"Sim, assim que voc\xEA terminar alguns trabalhos com o registro de tempo ligado. Cada lote mostra ent\xE3o quanto tempo os trabalhos devem levar no seu ritmo: no quadro de Foco e no **Plano de corre\xE7\xE3o** em Pend\xEAncias, e no cart\xE3o da atividade.","help.plan_grading_a2":"O quadro de Foco tamb\xE9m sugere um hor\xE1rio livre entre as suas aulas, retoma o \xFAltimo lote no trabalho em que voc\xEA parou e pode come\xE7ar pequeno com **3 trabalhos**. No dia que voc\xEA escolher, o In\xEDcio mostra um olhar sobre a semana. Cada um pode ser desligado em **Configura\xE7\xF5es, Foco e metas**.","help.plan_grading_w":"estimativa quanto tempo ritmo carga prazos hor\xE1rio livre continuar mais curtos passos pequenos olhar semanal sexta sil\xEAncio","help.plan_grading_go":"Abrir Ajustes, Foco e metas","help.session_goals_q":"Posso definir uma meta para cada sess\xE3o de foco?","help.session_goals_a1":"Sim. Antes de come\xE7ar, escolha uma em **Meta desta sess\xE3o**: alguns trabalhos, o lote inteiro, a tarefa ou algumas palavras suas. O app sugere uma pelo seu ritmo, e o cron\xF4metro mostra quanto voc\xEA j\xE1 fez.","help.session_goals_a2":"No fim da sess\xE3o, voc\xEA v\xEA se a alcan\xE7ou. Uma meta n\xE3o alcan\xE7ada passa para a sua pr\xF3xima sess\xE3o no mesmo trabalho, ent\xE3o um lote pode levar algumas sess\xF5es com pausas entre elas. **N\xE3o passar adiante** a deixa de lado.","help.session_goals_w":"meta sess\xE3o cada sess\xE3o passar adiante pr\xF3xima sess\xE3o pausa meta semanal dias terminar at\xE9 prazo trabalhos por dia","help.session_goals_go":"Abrir Ajustes, Foco e metas","help.school_resources_q":"Onde posso guardar os links e arquivos da minha escola?","help.school_resources_a1":"Em **Escola**, na barra lateral. Guarde ali o manual, o calend\xE1rio, os hor\xE1rios do sinal, os portais em que voc\xEA entra, formul\xE1rios e notas como para quem ligar. Coloque tudo em grupos com os nomes que quiser e clique na bandeira dos que voc\xEA mais abre para mant\xEA-los no topo.","help.school_resources_a2":"**Adicionar** e depois **Link** quando a escola mant\xE9m o material on-line, porque um link se atualiza sozinho. **Adicionar** e depois **Arquivo** guarda uma c\xF3pia de um arquivo com o seu trabalho, at\xE9 50 MB cada. Voc\xEA tamb\xE9m pode soltar arquivos na p\xE1gina ou colar um endere\xE7o da web.","help.school_resources_a3":"Marque uma turma em **Para uma turma** quando um link, arquivo ou nota for de uma s\xF3 turma. Assim a p\xE1gina pode mostrar uma turma por vez, e um link de uma turma aparece em todas as aulas dela, em **Links** e em **Apresentar**, o ano todo. Os links pr\xF3prios de uma aula v\xE3o nesse mesmo quadro **Links**, digitados ou escolhidos daqui.","help.school_resources_a4":"Tudo \xE9 salvo com o resto do seu trabalho: neste navegador, na sua pasta e em um arquivo para levar. Buscar encontra cada item pelo nome. **Pessoas**, no topo, tem um lugar para cada cargo, como a dire\xE7\xE3o. Preencha os que precisar ou use **Mudar os cargos…** para os cargos da sua escola.","help.school_resources_w":"manual calend\xE1rio regras portal favorito link arquivo documento recursos escola hor\xE1rio formul\xE1rios","help.school_resources_go":"A","help.language_q":"Posso usar o aplicativo em outro idioma?","help.language_a1":"Sim. Escolha um em Configura\xE7\xF5es, Exibi\xE7\xE3o, **Idioma**, ou no topo da tela de boas-vindas. A p\xE1gina \xE9 mostrada de novo no idioma escolhido.","help.language_a2":"Por enquanto, um idioma diferente do ingl\xEAs cobre as telas que o aplicativo atual traduz. Telas novas neste aplicativo ficam em ingl\xEAs at\xE9 que os textos delas sejam traduzidos.","help.language_a3":"Os nomes das turmas e dos alunos, e tudo o que voc\xEA digitou, nunca s\xE3o traduzidos.","help.language_w":"portugu\xEAs ingl\xEAs idioma l\xEDngua traduzir tradu\xE7\xE3o","help.language_go":"A","help.scan_split_q":"Digitalizei a turma inteira em um s\xF3 arquivo. Como divido?","help.scan_split_a1":"Abra a atividade na Linha do curso da turma, clique em **Trazer trabalhos**, depois em **Uma digitaliza\xE7\xE3o dos trabalhos de todos…** e escolha a digitaliza\xE7\xE3o.","help.scan_split_a2":"Arraste as p\xE1ginas para o nome de cada aluno. P\xE1ginas de cabe\xE7a para baixo ou tortas s\xE3o corrigidas e sinalizadas, com **Desfazer**. **Escanear de novo** marca uma p\xE1gina que n\xE3o d\xE1 para ler.","help.scan_split_a3":"Para uma digitaliza\xE7\xE3o de reposi\xE7\xE3o depois, use **Trazer arquivos** em Setup e ent\xE3o **Um escaneamento para dividir…**.","help.scan_split_w":"scanner pdf copiadora p\xE1ginas separar papel manuscrito","help.tools_q":"Quais s\xE3o as ferramentas de corre\xE7\xE3o?","help.tools_a1":"A faixa na borda esquerda da p\xE1gina tem Selecionar, Caneta, Marca-texto, C\xEDrculo, Texto, Coment\xE1rio, Visto e Borracha, e depois Desfazer e Refazer. Aponte para uma ferramenta para ver o nome e a tecla.","help.tools_a2":"Um clique direito na p\xE1gina oferece quase todas as ferramentas para um \xFAnico uso, e a ferramenta que voc\xEA tinha continua escolhida.","help.tools_a3":"Pressione **?** para ver todas as teclas.","help.tools_w":"caneta marca-texto desenhar escrever anotar c\xEDrculo borracha desfazer teclas atalhos","help.comment_q":"Como escrevo um coment\xE1rio no trabalho?","help.comment_a1":"Escolha **Coment\xE1rio** (C) e clique no ponto, ou arraste sobre palavras digitadas para destac\xE1-las. Uma caixa se abre na margem com uma linha at\xE9 o ponto.","help.comment_a2":"Pressione Enter ou clique fora da caixa para terminar; o que voc\xEA escreveu fica guardado. Shift Enter come\xE7a uma nova linha. Clique na caixa de novo para alterar o texto ou a cor. Arraste a linha para cima ou para baixo para que passe entre as linhas do texto, mesmo antes de escrever.","help.comment_a3":"Coment\xE1rios que voc\xEA usa muito podem ser salvos: **Coment\xE1rios salvos**, abaixo da caixa de coment\xE1rio do painel de notas.","help.comment_w":"nota margem coment\xE1rios anotar salvos banco","help.next_student_q":"Como passo de um aluno para outro?","help.next_student_a1":"Pressione **Enter** ou **N** para ir ao pr\xF3ximo trabalho que ainda precisa de nota. As setas ao lado do bot\xE3o v\xE3o ao trabalho anterior e ao seguinte.","help.next_student_a2":"A faixa estreita \xE0 esquerda \xE9 a lista de alunos. Aponte para ela para ver os nomes, pressione **[** para deix\xE1-la aberta ou **/** para digitar um nome.","help.next_student_w":"pr\xF3ximo anterior lista nomes faixa navegar","help.zoom_q":"Como dou zoom ou giro uma p\xE1gina?","help.zoom_a1":"Fa\xE7a o gesto de pin\xE7a no trackpad, segure Ctrl (⌘ em um Mac) e role, ou use o controle de zoom no canto inferior direito da p\xE1gina. Clique na porcentagem para voltar a 100%.","help.zoom_a2":"Para girar uma p\xE1gina, aponte para ela e use as setas do canto superior. **Girar todas as p\xE1ginas** fica no menu ⋯ do arquivo. Suas marca\xE7\xF5es giram com a p\xE1gina.","help.zoom_w":"girar rotacionar de lado de cabe\xE7a para baixo maior menor ampliar","help.lighting_q":"Uma digitaliza\xE7\xE3o est\xE1 clara demais para ler. O que posso fazer?","help.lighting_a1":"Abra **Ilumina\xE7\xE3o** pelo ⋯ ao lado do nome do aluno. H\xE1 brilho, contraste, escurecer a escrita e nitidez, para todos os alunos ou s\xF3 para este. **Corre\xE7\xE3o autom\xE1tica** faz uma primeira tentativa.","help.lighting_a2":"Lighting s\xF3 muda como a p\xE1gina \xE9 exibida. A digitaliza\xE7\xE3o em si nunca \xE9 alterada.","help.lighting_w":"escuro claro l\xE1pis fraco contraste brilho foto","help.word_files_q":"Posso corrigir arquivos do Word?","help.word_files_a1":"Sim. Um trabalho em Word abre como arquivo do Word, e a ferramenta Comment escreve coment\xE1rios reais do Word, que o aluno v\xEA na margem do Word.","help.word_files_a2":"Para desenhar nele com a caneta e o marca-texto, use **Converter em PDF** na barra do arquivo. O arquivo do Word \xE9 mantido. Em Configura\xE7\xF5es, Corre\xE7\xE3o, voc\xEA pode converter cada trabalho em Word ao abri-lo.","help.word_files_w":"docx doc microsoft converter pdf","help.word_files_go":"A","help.audio_q":"Posso avaliar grava\xE7\xF5es e v\xEDdeos?","help.audio_a1":"Sim. Uma grava\xE7\xE3o toca no alto do trabalho do aluno, com saltos de 10 segundos e velocidade de 1\xD7 a 2\xD7. **+ Tempo no coment\xE1rio** adiciona o momento, como [2:15], ao seu coment\xE1rio.","help.audio_a2":"A barra de espa\xE7o toca e pausa. J e L voltam e avan\xE7am 5 segundos.","help.audio_w":"\xE1udio mp3 mp4 v\xEDdeo oral semin\xE1rio apresenta\xE7\xE3o transcri\xE7\xE3o","help.quick_mark_q":"Como corrijo r\xE1pido uma prova em papel?","help.quick_mark_a1":"Abra **Corre\xE7\xE3o r\xE1pida** em Setup. Desenhe uma vez uma caixa em volta de cada quest\xE3o, na digitaliza\xE7\xE3o de qualquer aluno.","help.quick_mark_a2":"Depois corrija uma quest\xE3o para a turma toda, ou a prova inteira de um aluno. Cada quest\xE3o pode mostrar ✗ nas respostas erradas, ✓ e ✗, pontos ou uma escala com suas pr\xF3prias palavras.","help.quick_mark_a3":"O total vira a nota do aluno. Em d\xFAvida sobre uma resposta? Pressione **P** ou **⧉ Copiar** nela para copiar uma imagem s\xF3 dessa resposta, com a quest\xE3o e o seu gabarito em cima, para colar em um assistente de IA. O nome, a nota e a sua marca ficam de fora, mas a imagem ainda mostra a letra e as palavras do aluno.","help.quick_mark_a4":"Em uma turma do IB MYP, cada quest\xE3o conta para um crit\xE9rio. Em **De pontos para n\xEDveis**, na tela das caixas, digite a menor pontua\xE7\xE3o que d\xE1 cada n\xEDvel. O quiz passa ent\xE3o a dar um n\xEDvel por crit\xE9rio, sem total e sem porcentagem.","help.quick_mark_w":"prova teste quest\xF5es caixas certo errado pontos quiz","help.make_quiz_q":"Posso criar uma prova que se corrige sozinha pela digitaliza\xE7\xE3o?","help.make_quiz_a1":"Sim, para m\xFAltipla escolha, verdadeiro ou falso e marque todas as corretas. No cart\xE3o da tarefa, abra **⋯** e escolha **Criar uma prova**. Digite cada quest\xE3o, clique na letra certa e em **Imprimir**. Cada c\xF3pia leva o nome de um aluno e um c\xF3digo no topo.","help.make_quiz_a2":"Digitalize a pilha inteira em um PDF, em qualquer ordem, e escolha **Trazer a prova escaneada** no cart\xE3o. Cada p\xE1gina vai para o seu aluno pelo c\xF3digo, e as bolhas s\xE3o corrigidas. Respostas pouco claras s\xE3o mostradas para voc\xEA escolher.","help.make_quiz_a3":"Uma resposta curta tem um quadro do professor: preencha a bolha da nota ao corrigir e a digitaliza\xE7\xE3o a l\xEA tamb\xE9m, ou corrija em **Corre\xE7\xE3o r\xE1pida**. Se mudar a prova depois de imprimir e as bolhas mudarem de lugar, imprima de novo.","help.make_quiz_w":"bolhas m\xFAltipla escolha verdadeiro falso digitalizar imprimir folha de respostas","help.screenshot_q":"Como fa\xE7o uma captura de tela?","help.screenshot_a1":"Pressione **S** em um trabalho, **Alt S** (⌥S no Mac) em qualquer lugar do aplicativo, ou o bot\xE3o de captura ao p\xE9 das ferramentas de corre\xE7\xE3o. Arraste sobre o que voc\xEA quer, clique em uma p\xE1gina para a p\xE1gina inteira, ou pressione Enter para tudo o que est\xE1 na tela. A imagem vai para a \xE1rea de transfer\xEAncia, pronta para colar.","help.screenshot_a2":"Em um trabalho, a p\xE1gina \xE9 desenhada de novo a partir do arquivo: as coberturas de nome s\xE3o pintadas, e o nome do aluno e o nome do arquivo acima do trabalho ficam de fora. Desmarque **Com as minhas marcas** para a p\xE1gina sem as suas marcas. Todo o resto, como a lista de alunos, aparece como est\xE1 na tela. Nada \xE9 enviado a lugar nenhum.","help.screenshot_w":"captura de tela print recorte imagem copiar \xE1rea de transfer\xEAncia","help.mark_colors_q":"Posso mudar a cor do ✗, dos vistos e dos pontos?","help.mark_colors_a1":"Sim. Em Configura\xE7\xF5es, Marking, **Cores das marcas**, ou no menu **Cores** do Quick mark. O ✗ usa a cor da sua caneta e os vistos t\xEAm a deles.","help.mark_colors_a2":"Os pontos escritos em um trabalho, como 1/2, ficam na cor do ✗, a menos que voc\xEA escolha outra. **Pelo acerto** escreve a pontua\xE7\xE3o total na cor do visto, a parcial em \xE2mbar e zero na cor do ✗: verde, \xE2mbar e vermelho, se voc\xEA mantiver essas cores.","help.mark_colors_a3":"Os totais e os carimbos de nota ficam na cor de pontos que voc\xEA escolher, ou na cor do ✗ com Pelo acerto. No Quick mark, as marcas j\xE1 dadas no quiz mudam para as novas cores.","help.mark_colors_w":"cor vermelho verde visto xis pontos caneta","help.mark_colors_go":"A","help.late_work_q":"Um aluno entregou atrasado. Como adiciono o trabalho?","help.late_work_a1":"Com a atividade aberta, clique em **+ Add** acima da p\xE1gina e escolha **Um arquivo…**, ou solte o arquivo sobre o nome do aluno.","help.late_work_a2":"Para v\xE1rios arquivos atrasados de uma vez, use **Trazer arquivos** em Setup. O que j\xE1 est\xE1 aqui fica de fora, ent\xE3o s\xF3 restam os arquivos novos para colocar. Marque **Atrasado** ao lado de quem deve aparecer como atrasado.","help.late_work_w":"atrasado faltando adicionar arquivo reenviar nova entrega","help.ib_myp_q":"Dou aula no IB MYP (PAI). Como avalio por crit\xE9rios e chego \xE0 nota de 1 a 7?","help.ib_myp_a1":"Na p\xE1gina da turma, clique em **Avalia\xE7\xE3o** e escolha **PAI do IB**. Escolha o seu grupo de disciplinas para receber os quatro crit\xE9rios dele, e altere qualquer nome ou limite de nota.","help.ib_myp_a2":"1. Abra uma tarefa dessa turma e clique em **Escolha os crit\xE9rios desta tarefa**. Marque os crit\xE9rios que a tarefa avalia. Cada um vira uma linha de 0 a 8, sem total e sem porcentagem.","help.ib_myp_a3":"2. Na aba **Notas** da turma, cada tarefa mostra os n\xEDveis que deu. Clique num n\xEDvel \xE0 direita para ver todas as evid\xEAncias de um aluno num crit\xE9rio e escolher o n\xEDvel que melhor se encaixa.","help.ib_myp_a4":"3. Quando cada crit\xE9rio tiver um n\xEDvel, o total vira a nota final de 1 a 7. Os n\xEDveis nunca s\xE3o calculados em m\xE9dia por voc\xEA. Para uma tarefa corrigida no papel, use **+ Adicionar n\xEDveis** na aba Notas.","help.ib_myp_w":"ib myp pai crit\xE9rios n\xEDveis 0 a 8 bacharelado internacional","help.ib_dp_q":"Dou aula no IB DP. De onde v\xEAm as notas de 1 a 7?","help.ib_dp_a1":"Na p\xE1gina da turma, clique em **Avalia\xE7\xE3o** e escolha **PD do IB**, depois digite a menor porcentagem que d\xE1 cada nota na sua disciplina. Os limites variam por disciplina e por sess\xE3o, ent\xE3o os que aparecem no in\xEDcio s\xE3o s\xF3 um ponto de partida.","help.ib_dp_a2":"A aba Notas passa ent\xE3o a mostrar o 1 a 7 ao lado da porcentagem do per\xEDodo de cada aluno.","help.ib_dp_a3":"No mesmo quadro, **Componentes** define quanto cada tipo de trabalho conta s\xF3 nesta turma. Na aba Notas, **Notas previstas** abre uma lista em que voc\xEA clica na nota que prev\xEA para cada aluno. A nota que a porcentagem alcan\xE7a aparece contornada como dica.","help.ib_dp_w":"ib dp diploma limites 1 a 7 notas previstas componentes","help.group_work_q":"V\xE1rios alunos fizeram um trabalho juntos. Corrijo para cada um?","help.group_work_a1":"N\xE3o. Abra o menu ⋯ do arquivo, escolha **Trabalho em grupo…** e clique em cada parceiro.","help.group_work_a2":"Com **Corrigir e avaliar uma vez para o grupo** ativado, uma marca\xE7\xE3o ou nota dada a um parceiro vale para todos, e cada um recebe o trabalho corrigido.","help.group_work_w":"parceiros duplas grupo cartaz compartilhado juntos equipe","help.video_q":"Como avalio uma apresenta\xE7\xE3o ou um v\xEDdeo em vez de um trabalho escrito?","help.video_a1":"No cart\xE3o da tarefa, clique em **Add papers…** e escolha **No papers: presentations or videos…**. Cada aluno da lista ganha uma p\xE1gina de anota\xE7\xF5es para voc\xEA escrever enquanto assiste. Ela \xE9 corrigida, recebe nota e \xE9 devolvida como um trabalho.","help.video_a2":"Para uma grava\xE7\xE3o, abra um aluno, clique em **+ Add** e escolha **A video…**. Cole o link (Google Drive, YouTube ou outro lugar) e marque os colegas que aparecem nele. Um \xFAnico conjunto de anota\xE7\xF5es e uma \xFAnica nota valem ent\xE3o para o grupo.","help.video_a3":"S\xF3 o link \xE9 guardado, ent\xE3o o v\xEDdeo fica onde est\xE1. Um estudante com um v\xEDdeo e uma p\xE1gina de anota\xE7\xF5es abre lado a lado: o v\xEDdeo em um painel \xE0 direita e a p\xE1gina de anota\xE7\xF5es ao lado. **Reproduzir aqui** inicia o v\xEDdeo, e **Abrir em uma janela pr\xF3pria** o coloca fora do aplicativo. **+ Add** tamb\xE9m tem **Uma p\xE1gina de anota\xE7\xF5es…**.","help.video_a4":"Para guardar um trecho que vale mostrar \xE0 turma, clique em **+ Clip** abaixo do v\xEDdeo e informe os tempos e um t\xEDtulo; **Editar** os altera depois. **Mostrar para a turma** o reproduz em tela cheia com o t\xEDtulo e sem o nome do aluno. **Trechos para mostrar \xE0 turma**, em Setup, reproduz todos em sequ\xEAncia.","help.video_w":"apresenta\xE7\xE3o semin\xE1rio oral v\xEDdeo grava\xE7\xE3o link youtube drive trecho","help.tablet_q":"Posso corrigir em um tablet com caneta?","help.tablet_a1":"Sim. Abra o aplicativo no navegador do tablet. Uma caneta desenha com a ferramenta escolhida, e com a caneta de desenho a linha fica mais larga onde voc\xEA aperta mais.","help.tablet_a2":"Depois que voc\xEA usa uma caneta, um dedo move a p\xE1gina e dois dedos fazem pin\xE7a para dar zoom. Sua m\xE3o pode descansar na tela enquanto voc\xEA escreve. At\xE9 uma caneta ser usada, um dedo desenha e dois dedos movem a p\xE1gina.","help.tablet_a3":"Para mudar o que um dedo faz, ou desligar a linha mais larga, v\xE1 em Configura\xE7\xF5es, Corre\xE7\xE3o, **Tablet e caneta**.","help.tablet_a4":"Isso foi testado com caneta e dedos simulados, ainda n\xE3o em todos os tablets. Se algo n\xE3o funcionar bem no seu, um notebook com mouse ou trackpad funciona como sempre.","help.tablet_w":"ipad caneta pencil stylus toque surface tablet dedo palma pin\xE7a zoom rolar press\xE3o","help.tablet_go":"A","help.rubric_q":"Como dou nota com uma rubrica?","help.rubric_a1":"O painel de notas fica \xE0 direita da p\xE1gina. Cada crit\xE9rio da rubrica tem um controle deslizante de 4 a 0, com meios pontos. Arraste-o ou clique em um n\xFAmero.","help.rubric_a2":"Pelo teclado: pressione de **1** a **4** (ou **0**) para dar nota ao crit\xE9rio ativo, um **ponto** para meio ponto e **Enter** para o pr\xF3ximo trabalho.","help.rubric_w":"nota avaliar controle crit\xE9rios teclado meios pontos","help.rubric_setup_q":"Como mudo os crit\xE9rios da rubrica ou uso pontos?","help.rubric_setup_a1":"Clique em **Editar** acima da rubrica, ou em **Configurar rubrica** em Setup. Renomeie, adicione ou remova crit\xE9rios e escreva o que cada nota significa em um crit\xE9rio.","help.rubric_setup_a2":"A mesma janela muda a atividade para pontos simples e define a escala que converte um total em porcentagem.","help.rubric_setup_a3":"**Salvar no banco…** guarda uma rubrica para usar em outra atividade.","help.rubric_setup_a4":"Um crit\xE9rio vale de 0 a 4 com meio ponto, a menos que voc\xEA diga outra coisa. Abaixo dos crit\xE9rios, escolha outra nota m\xE1xima (de 1 a 10) ou desligue o meio ponto. A sua escala habitual para rubricas novas fica em Configura\xE7\xF5es, Avalia\xE7\xE3o e escalas.","help.rubric_setup_w":"crit\xE9rios n\xEDveis descritores pontos porcentagem escala editar banco reutilizar","help.side_pane_q":"Posso ver duas coisas lado a lado enquanto corrijo?","help.side_pane_a1":"Sim. Clique em **Lado a lado** acima do trabalho, ou use a tecla **B**. Um painel abre ao lado do trabalho, e as abas no alto dele escolhem o que ele mostra: o v\xEDdeo do estudante, a p\xE1gina de anota\xE7\xF5es, outro arquivo dele ou a **Rubrica** com o que cada pontua\xE7\xE3o significa.","help.side_pane_a2":"Cada lado rola por conta pr\xF3pria, e a caneta funciona em uma p\xE1gina de qualquer um deles. Clique em uma caixa na aba Rubrica para dar aquela pontua\xE7\xE3o. Um v\xEDdeo levado para o painel continua tocando.","help.side_pane_a3":"Arraste a barra entre os dois para mudar os tamanhos; um clique duplo a p\xF5e de volta. **⋯** no painel o leva para a esquerda ou para cima, de ponta a ponta, o que serve bem em uma janela estreita. No **⋯** de um arquivo, **Show beside** p\xF5e esse arquivo no painel.","help.side_pane_a4":"O painel fica aberto de um estudante para o outro at\xE9 voc\xEA fech\xE1-lo com **✕** ou **B**. Um estudante com um v\xEDdeo e uma p\xE1gina de anota\xE7\xF5es abre lado a lado sem voc\xEA pedir, a n\xE3o ser que voc\xEA tenha fechado o painel em um v\xEDdeo antes.","help.side_pane_w":"painel dividido lado a lado dois pain\xE9is ao lado rubrica v\xEDdeo anota\xE7\xF5es comparar divisor split side","help.typed_notes_q":"Posso digitar minhas anota\xE7\xF5es em vez de escrever numa p\xE1gina?","help.typed_notes_a1":"Sim. Abra **Lado a lado** e escolha **Digitar anota\xE7\xF5es**. \xC9 uma p\xE1gina em que voc\xEA digita como em qualquer documento, com t\xEDtulos, listas, negrito, it\xE1lico, sublinhado e destaque na barra de cima. Numa p\xE1gina de notas, **Digitar anota\xE7\xF5es em vez disso** tamb\xE9m a abre. Funciona em qualquer atividade.","help.typed_notes_a2":"Ao lado de um v\xEDdeo tocando, ou com o cron\xF4metro do rodap\xE9 rodando para uma apresenta\xE7\xE3o ao vivo, cada novo par\xE1grafo ganha seu tempo na margem. Clique num tempo para tocar o v\xEDdeo a partir dali. **Tempo** p\xF5e ou tira \xE0 m\xE3o, e **Tempos** no **⋯** desliga isso.","help.typed_notes_a3":"Um par\xE1grafo pode ser marcado como ponto forte, pr\xF3ximo passo ou pergunta com **Marcar**. A marca aparece ao lado e \xE9 opcional. **⋯** tem **Usar estes t\xEDtulos para todos os alunos**, para que cada aluno comece com os mesmos t\xEDtulos.","help.typed_notes_a4":"A linha no rodap\xE9 diz se as anota\xE7\xF5es voltam para o aluno como uma p\xE1gina do trabalho corrigido. Clique nela para mudar isso para a atividade toda. **Tamanho do texto para o aluno** no **⋯** deixa essa p\xE1gina Compacta, Padr\xE3o ou Grande.","help.typed_notes_w":"digitar anota\xE7\xF5es notas linhas teclado apresenta\xE7\xE3o semin\xE1rio v\xEDdeo cron\xF4metro t\xEDtulos ponto forte pr\xF3ximo passo pergunta copiar devolver","help.ai_beside_q":"Posso deixar meu assistente de IA aberto ao lado do aplicativo?","help.ai_beside_a1":"Sim. Informe o seu assistente em **Configura\xE7\xF5es**, **Trabalhar com IA**, e o nome dele aparece perto da parte de baixo da barra lateral em todas as telas. Clique nele e o assistente abre numa janela \xE0 direita da tela. Se a janela do aplicativo cobrir o assistente, deixe essa janela mais estreita para os dois aparecerem.","help.ai_beside_a2":"No Chrome h\xE1 um jeito mais organizado: clique com o bot\xE3o direito no nome na barra lateral e escolha **Abrir link em visualiza\xE7\xE3o dividida**. Os dois ficam ent\xE3o numa s\xF3 janela, com um divisor que voc\xEA pode arrastar. N\xE3o d\xE1 para juntar mais do que isso, porque os assistentes n\xE3o deixam suas p\xE1ginas serem mostradas dentro de outro aplicativo.","help.ai_beside_a3":"**Abre em**, na mesma parte das Configura\xE7\xF5es, aceita um link seu, por exemplo para sua conta da escola, um Gem, um projeto ou um GPT personalizado. Se o assistente abrir na conta errada, troque de conta l\xE1, copie o endere\xE7o e cole.","help.ai_beside_a4":"O aplicativo n\xE3o envia nada ao assistente. Ele s\xF3 v\xEA o que voc\xEA cola ou anexa. Um assistente embutido no pr\xF3prio navegador, como um bot\xE3o de assistente na barra de ferramentas do navegador, \xE9 diferente: ele pode ler a p\xE1gina em que voc\xEA est\xE1, incluindo nomes de alunos, quando voc\xEA pergunta sobre ela.","help.ai_beside_w":"gemini claude chatgpt copilot ia assistente tela dividida lado a lado janela ao lado chat","help.ai_beside_go":"I","help.talk_timer_q":"Posso cronometrar uma apresenta\xE7\xE3o ao vivo?","help.talk_timer_a1":"Sim. D\xEA ao estudante uma p\xE1gina de anota\xE7\xF5es (**+ Add**, **Uma p\xE1gina de anota\xE7\xF5es…**), clique em **Lado a lado** e escolha a aba **Cron\xF4metro**. **Come\xE7ar** p\xF5e um cron\xF4metro para rodar ao lado da p\xE1gina de anota\xE7\xF5es, e **+ Tempo no coment\xE1rio** escreve o tempo no seu coment\xE1rio, como [2:15]. Cada estudante tem o pr\xF3prio rel\xF3gio.","help.talk_timer_a2":"Digite a **Dura\xE7\xE3o pedida** em minutos e o rel\xF3gio mostra se a fala est\xE1 mais curta, dentro ou mais longa. Em uma grava\xE7\xE3o, um v\xEDdeo do YouTube ou do Vimeo tocado aqui tem bot\xF5es para pular 10 segundos e mudar a velocidade, e **Flutuar** mant\xE9m um arquivo de v\xEDdeo em uma janelinha sempre por cima. O player do Google Drive n\xE3o pode ser controlado daqui.","help.talk_timer_w":"cron\xF4metro temporizador tempo dura\xE7\xE3o apresenta\xE7\xE3o ao vivo minutos velocidade pular flutuar timer","help.ai_switch_q":"Uso mais de um assistente de IA. Posso trocar de um para outro?","help.ai_switch_a1":"Sim. Clique no nome do seu assistente na barra lateral e os outros aparecem embaixo. Escolha um: ele abre ao lado do aplicativo e passa a ser o assistente em uso, e os textos da tela acompanham.","help.ai_switch_a2":"Cada um guarda o pr\xF3prio link. Para dar a um deles um link seu, torne-o o assistente em uso e preencha **Abre em** em **Configura\xE7\xF5es**, **Trabalhar com IA**. **Outros que voc\xEA usa**, no mesmo lugar, escolhe quais aparecem na lista.","help.ai_switch_w":"gemini claude chatgpt copilot trocar mudar outro assistente lista escolher switch","help.ai_switch_go":"I","help.my_setup_q":"Um assistente de IA pode configurar o aplicativo para mim?","help.my_setup_a1":"Sim. Configura\xE7\xF5es, **Turmas e per\xEDodos**, **Minha configura\xE7\xE3o** tem um comando para copiar em qualquer assistente de IA. Ele usa o que j\xE1 sabe sobre o seu ensino, pergunta o resto e entrega um \xFAnico bloco de texto de configura\xE7\xE3o: turmas e quando se re\xFAnem, o calend\xE1rio, per\xEDodos, como voc\xEA avalia, rubricas, coment\xE1rios salvos e objetivos de aprendizagem.","help.my_setup_a2":"Cole esse texto na mesma p\xE1gina e clique em **Conferir**. Voc\xEA v\xEA o que mudaria, desmarca o que n\xE3o quiser e pode desfazer depois.","help.my_setup_a3":"Uma configura\xE7\xE3o nunca leva alunos. O prompt pede ao assistente que os deixe de fora, e qualquer coisa sobre um aluno no texto \xE9 deixada de fora e avisada. O aplicativo n\xE3o envia nada: \xE9 voc\xEA quem leva o texto.","help.my_setup_a4":"**Copiar minha configura\xE7\xE3o**, na mesma p\xE1gina, d\xE1 a sua pr\xF3pria configura\xE7\xE3o no mesmo tipo de texto, para um colega come\xE7ar a partir dela.","help.my_setup_w":"configura\xE7\xE3o configurar importar assistente ia chatgpt claude gemini colega","help.my_setup_go":"Abrir Turmas e per\xEDodos","help.grading_way_q":"Minha escola avalia com conceitos, porcentagens ou de 1 a 7. Posso configurar isso?","help.grading_way_a1":"Sim. Configura\xE7\xF5es, **Avalia\xE7\xE3o e escalas** tem como voc\xEA avalia: crit\xE9rios de rubrica, pontos, porcentagem, conceitos, crit\xE9rios do PAI (IB MYP) (0 a 8) ou IB DP de 1 a 7, com os limites de cada conceito ou n\xEDvel.","help.grading_way_a2":"\xC9 o seu ponto de partida para atividades novas. Cada atividade pode ser configurada do seu jeito em Rubric setup.","help.grading_way_w":"conceitos A B C porcentagem IB 7 limites faixas escala","help.grading_way_go":"Abrir Avalia\xE7\xE3o e escalas","help.status_q":"Como marco um trabalho como n\xE3o entregue, dispensado ou atrasado?","help.status_a1":"Abaixo do total do aluno no painel de notas, escolha **N\xE3o entregue**, **Dispensado** ou **Atrasado**. O ⋯ ao lado tem **Deixar fora da m\xE9dia**.","help.status_a2":"Trabalhos n\xE3o entregues e dispensados n\xE3o esperam nota, ent\xE3o n\xE3o contam como pendentes de corre\xE7\xE3o.","help.status_w":"ausente sem trabalho dispensado atrasado status faltando","help.extra_credit_q":"Como dou pontos extras?","help.extra_credit_a1":"Em um trabalho, abra o ⋯ ao lado da nota e escolha **Pontos extras**. Aceita pontos ou uma porcentagem.","help.extra_credit_a2":"Para pontos extras que n\xE3o est\xE3o ligados a um trabalho, clique em **+ Pontos extras** na aba **Notas** da turma. Configurar per\xEDodos diz se eles somam na nota do per\xEDodo e se uma nota pode passar de 100%.","help.extra_credit_w":"b\xF4nus pontos extras adicional","help.retake_q":"Um aluno est\xE1 refazendo uma tarefa. Como guardo a primeira nota?","help.retake_a1":"Abra o ⋯ ao lado de Missing, Excused e Late no trabalho dele e escolha **Come\xE7ar uma nova tentativa**. A nota, o coment\xE1rio e o trabalho da primeira tentativa s\xE3o guardados, e o painel de notas se esvazia para a nova tentativa. Adicione o novo trabalho com **+ Add**.","help.retake_a2":"A maior tentativa conta, a menos que voc\xEA escolha a mais recente ou a m\xE9dia: **Mudar** no quadro de refa\xE7\xE3o, ou Configurar per\xEDodos na aba Notas. \xC9 uma regra s\xF3 para todas as suas turmas.","help.retake_a3":"Para uma nota que voc\xEA digitou na aba Notas, digite as duas na c\xE9lula, assim: **7 > 10**.","help.retake_w":"refazer recupera\xE7\xE3o segunda tentativa nova tentativa reavalia\xE7\xE3o","help.past_work_q":"Posso ver trabalhos anteriores de um aluno enquanto corrijo?","help.past_work_a1":"Sim. **Trabalhos anteriores**, abaixo de Next no painel de notas, mostra as notas do aluno e seus coment\xE1rios em outras atividades ao lado do trabalho na tela.","help.past_work_a2":"Os alunos s\xE3o associados pela lista da turma.","help.past_work_w":"hist\xF3rico anterior pr\xE9vio progresso comparar","help.return_q":"Como devolvo os trabalhos corrigidos?","help.return_a1":"1. Abra a aba **Devolver** da atividade. Ela mostra primeiro o que falta: notas n\xE3o dadas, alunos sem trabalho.","help.return_a2":"2. Clique no bot\xE3o azul. O aplicativo cria um ZIP com o arquivo corrigido de cada aluno nas mesmas pastas em que chegaram, com nomes como “Ana Lee - River essay - Graded.pdf” (Feedback quando n\xE3o h\xE1 nota).","help.return_a3":"3. Envie esse ZIP, ou os arquivos dentro dele, para o sistema da sua escola.","help.return_a4":"Para devolver um s\xF3 trabalho na hora, use o bot\xE3o **Export … paper now** abaixo de Previous e Next.","help.return_w":"exportar baixar devolver entregar zip enviar alunos","help.anchor_papers_q":"Como escolho e exporto trabalhos de refer\xEAncia?","help.anchor_papers_a1":"Trabalhos de refer\xEAncia s\xE3o o trabalho alto, o m\xE9dio e o baixo que a sua escola guarda de uma avalia\xE7\xE3o somativa. Enquanto corrige, clique em **Alto**, **M\xE9dio** ou **Baixo** abaixo da nota. Cada n\xEDvel pertence a um s\xF3 trabalho, ent\xE3o escolher outro trabalho move o n\xEDvel.","help.anchor_papers_a2":"A aba **Devolver** lista os tr\xEAs. **Exportar trabalhos de refer\xEAncia** baixa os tr\xEAs em um ZIP, cada um com o nome da tarefa e do n\xEDvel, como “Persuasive essay - Summative High.pdf”.","help.anchor_papers_a3":"Os nomes dos alunos s\xE3o cobertos do mesmo jeito que para um assistente de IA: nomes digitados e as suas pr\xF3prias caixas de cobertura ficam pretos. Um nome escrito \xE0 m\xE3o precisa de uma caixa, ent\xE3o use antes **Conferir as coberturas** no cart\xE3o. Desmarque **Cobrir nomes dos alunos** para exportar como est\xE3o.","help.anchor_papers_w":"trabalhos de refer\xEAncia \xE2ncora alto m\xE9dio baixo somativa exemplos","help.feedback_page_q":"O que \xE9 a p\xE1gina de coment\xE1rios de um trabalho devolvido?","help.feedback_page_a1":"Cada trabalho devolvido come\xE7a com uma p\xE1gina para o aluno: a nota, cada crit\xE9rio da rubrica com o n\xEDvel que voc\xEA deu e o que ele significa, seu coment\xE1rio e cada coment\xE1rio do trabalho com o n\xFAmero da p\xE1gina.","help.feedback_page_a2":"Ela fica ativada at\xE9 voc\xEA desativ\xE1-la em **Op\xE7\xF5es**, na aba Return. Suas pr\xF3prias p\xE1ginas n\xE3o mudam. Com o aplicativo em portugu\xEAs, essa p\xE1gina sai em portugu\xEAs.","help.feedback_page_w":"capa resumo primeira p\xE1gina aluno v\xEA relat\xF3rio","help.copy_grades_q":"Como passo as notas para o sistema de notas da minha escola?","help.copy_grades_a1":"Abra a aba **Notas** da atividade. Ela lista cada aluno com as notas por crit\xE9rio, o total, a porcentagem e seu coment\xE1rio. Clique em qualquer c\xE9lula para copi\xE1-la e cole no sistema da sua escola.","help.copy_grades_a2":"A ordem pode seguir as pastas ou a sua lista, o que combinar com a tela onde voc\xEA cola.","help.copy_grades_w":"copiar colar managebac canvas transferir lan\xE7ar notas","help.change_after_q":"Posso alterar as marca\xE7\xF5es depois de exportar?","help.change_after_a1":"Sim. Suas marca\xE7\xF5es ficam no aplicativo, ent\xE3o abra a atividade, altere e exporte de novo.","help.change_after_a2":"Com **Manter as marca\xE7\xF5es edit\xE1veis** marcado na aba Return, cada PDF exportado leva tamb\xE9m suas marca\xE7\xF5es. Ao abrir essa exporta\xE7\xE3o em outro computador, elas voltam como marca\xE7\xF5es que voc\xEA pode mover ou apagar.","help.change_after_w":"editar corrigir refazer reexportar erro","help.gradebook_q":"Onde fica o di\xE1rio de notas?","help.gradebook_a1":"Abra uma turma pela barra lateral e escolha a aba **Notas**. Ela tem todas as atividades da turma numa tabela, agrupadas por tipo, com uma m\xE9dia por tipo e uma nota do per\xEDodo.","help.gradebook_a2":"**+ Adicionar notas** permite digitar notas de trabalhos que n\xE3o foram corrigidos aqui.","help.gradebook_a3":"Para digitar notas direto na tabela, clique em uma c\xE9lula ou comece a digitar nela. **Enter** vai para o pr\xF3ximo aluno e **Tab** para a pr\xF3xima atividade, e uma coluna copiada de uma planilha pode ser colada na primeira c\xE9lula.","help.gradebook_w":"notas tabela per\xEDodo m\xE9dia geral di\xE1rio","help.import_scores_q":"Posso trazer as notas do meu di\xE1rio antigo?","help.import_scores_a1":"Sim. Na aba **Notas** da turma, clique em **Importar…** e escolha um arquivo CSV ou Excel, ou cole as c\xE9lulas da sua planilha. Uma linha por aluno, uma coluna por atividade.","help.import_scores_a2":"Antes de salvar qualquer coisa, voc\xEA v\xEA cada coluna com o tipo, a data e o valor m\xE1ximo, quais linhas batem com a sua lista e qualquer nota que j\xE1 esteja na aba Notas. As notas que j\xE1 est\xE3o l\xE1 ficam, a menos que voc\xEA escolha as do arquivo.","help.import_scores_w":"importar csv excel planilha colar notas antigas","help.google_classroom_q":"Posso trazer uma turma do Google Classroom?","help.google_classroom_a1":"Sim, com dois downloads e sem login. Em Configura\xE7\xF5es, **Turmas e per\xEDodos**, clique em **Do Google Classroom…**.","help.google_classroom_a2":"Primeiro o arquivo de notas: no Classroom, abra a p\xE1gina de trabalhos dos alunos de qualquer atividade, clique na engrenagem e escolha baixar todas as notas como CSV. Ele traz os alunos, cada atividade com pontos e data, e as notas. Voc\xEA confere as notas antes de qualquer coisa ser salva na aba Notas.","help.google_classroom_a3":"Para os trabalhos, abra a pasta Classroom no Google Drive, depois a turma, depois a pasta da atividade, e baixe-a. Traga esse ZIP na atividade. Arquivos com nome “Nome do aluno - t\xEDtulo” s\xE3o reunidos sob cada aluno. Um arquivo que um aluno enviou com o pr\xF3prio nome abre como uma entrada separada para voc\xEA associar.","help.google_classroom_a4":"Os dois arquivos s\xE3o lidos neste navegador e nada \xE9 enviado a lugar nenhum. As notas n\xE3o podem ser enviadas de volta ao Google Classroom daqui: a aba Grades as lista para voc\xEA copiar.","help.google_classroom_w":"google classroom importar drive csv notas lista mudar transferir","help.google_classroom_go":"Abrir Turmas e per\xEDodos","help.terms_q":"Como configuro os per\xEDodos e quanto cada tipo vale?","help.terms_a1":"Configura\xE7\xF5es, **Turmas e per\xEDodos** tem os seus per\xEDodos e as datas deles, e quanto da nota do per\xEDodo cada tipo de atividade vale. Trabalho formativo nunca conta para a nota.","help.terms_a2":"Uma atividade conta para o per\xEDodo em que cai sua data de entrega.","help.terms_w":"semestre bimestre trimestre pesos porcentagem somativa formativa pondera\xE7\xE3o","help.terms_go":"Abrir Turmas e per\xEDodos","help.types_q":"Posso criar meus pr\xF3prios tipos de tarefa, ou mudar a ordem deles?","help.types_a1":"Sim. Abra **Configurar per\xEDodos** na aba **Notas** de uma turma ou em Configura\xE7\xF5es, **Turmas e per\xEDodos**. Em **Tipos e do que uma nota \xE9 feita** voc\xEA pode renomear um tipo, criar os seus com **+ Adicionar um tipo** (Li\xE7\xE3o de casa, Projetos, Testes) e dar a cada um a sua parte da nota.","help.types_a2":"As setas ao lado de cada tipo definem a ordem. \xC9 a ordem das colunas do di\xE1rio de notas, da esquerda para a direita, e das op\xE7\xF5es em todo lugar onde voc\xEA escolhe um tipo.","help.types_a3":"Um tipo pode ser removido quando n\xE3o houver mais nenhuma tarefa nele. O formativo continua sendo s\xF3 coment\xE1rio: um ✓ no lugar de uma nota.","help.types_w":"tipos categorias li\xE7\xE3o de casa projetos quizzes pesos ordem colunas","help.types_go":"Abrir Turmas e per\xEDodos","help.one_student_q":"Como vejo tudo sobre um aluno?","help.one_student_a1":"Abra a turma, escolha **Pessoas** e clique num nome. A p\xE1gina do aluno tem todas as notas, a nota do per\xEDodo e como ele est\xE1 evoluindo.","help.one_student_a2":"Os **Gr\xE1ficos** na aba **Notas** da turma mostram os mesmos n\xFAmeros para todos de uma vez.","help.one_student_w":"perfil individual fam\xEDlia reuni\xE3o conselho progresso gr\xE1fico","help.attendance_q":"Posso fazer a chamada no aplicativo?","help.attendance_a1":"Sim. Abra uma turma, escolha **Pessoas** e depois **Frequ\xEAncia**. Todos come\xE7am como presentes, ent\xE3o clique em **Atrasado** ou **Ausente, motivo desconhecido** s\xF3 para quem n\xE3o estiver, ou em **Todos est\xE3o aqui** se estiverem todos. Cada clique \xE9 salvo, com uma nota se voc\xEA quiser.","help.attendance_a2":"Quando souber que uma falta \xE9 justificada, abra aquele dia e clique em **Ausente, justificado**. **Ver dias anteriores** lista as faltas que ainda est\xE3o sem motivo.","help.attendance_a3":"**Ver dias anteriores** mostra todos os dias salvos em uma tabela, com os totais de cada aluno. **Copiar este dia** e **Baixar como planilha** levam os dados para o sistema da sua escola.","help.attendance_a4":"A frequ\xEAncia fica neste navegador e na sua pasta, como o resto do seu trabalho. Se voc\xEA n\xE3o usa, desligue em Configura\xE7\xF5es, **Turmas e per\xEDodos**.","help.attendance_w":"chamada frequ\xEAncia presen\xE7a falta atraso justificada ausente","help.attendance_go":"Abrir Turmas e per\xEDodos","help.learning_goals_q":"Posso ver as notas por objetivo de aprendizagem ou habilidade?","help.learning_goals_a1":"Sim, e \xE9 opcional. Em Configura\xE7\xF5es, Avalia\xE7\xE3o e escalas, **Objetivos de aprendizagem** guarda a sua pr\xF3pria lista: uma habilidade como “Usa evid\xEAncias” ou um padr\xE3o da sua escola.","help.learning_goals_a2":"1. Em uma tarefa, escolha Setup, depois **Configurar rubrica**, e escolha um objetivo ao lado de cada linha. Para um quiz em papel, escolha um objetivo abaixo de cada quest\xE3o em **Quadros da prova**.","help.learning_goals_a3":"2. Abra a aba **Notas** da turma e escolha **Objetivos**: a m\xE9dia da turma em cada objetivo, com a menor primeiro, cada aluno em cada objetivo e de onde veio cada n\xFAmero.","help.learning_goals_a4":"A p\xE1gina de um aluno mostra os objetivos dele ao lado da m\xE9dia da turma. Associar um objetivo nunca muda uma nota, e toda tarefa conta igual dentro de um objetivo.","help.learning_goals_w":"objetivos habilidades compet\xEAncias bncc padr\xF5es aprendizagem retomar","help.learning_goals_go":"Abrir Avalia\xE7\xE3o e escalas","help.report_comments_q":"Ele pode me ajudar a escrever os coment\xE1rios do boletim?","help.report_comments_a1":"Sim. Abra a aba **Notas** da turma e escolha **Coment\xE1rios de boletim**. Cada aluno tem um rascunho feito a partir da nota do per\xEDodo, dos crit\xE9rios de rubrica mais fortes e mais fracos, dos trabalhos pendentes e de como as notas mudaram.","help.report_comments_a2":"Altere o que quiser, traga o que voc\xEA escreveu nos trabalhos com **Adicionar** e clique em **Feito, pr\xF3ximo aluno**. **Copiar todos** copia todos os coment\xE1rios para o seu sistema de boletins.","help.report_comments_a3":"Nenhuma IA escreve os rascunhos e nada \xE9 enviado a lugar nenhum. **Reda\xE7\xE3o…** permite reescrever as frases com que eles s\xE3o montados. Por enquanto os rascunhos s\xE3o escritos em ingl\xEAs.","help.report_comments_w":"boletim relat\xF3rio per\xEDodo coment\xE1rio fim de bimestre parecer fam\xEDlias","help.seating_q":"Posso fazer um mapa de sala, grupos, ou sortear um aluno?","help.seating_a1":"Sim. Abra uma turma, escolha **Pessoas** e depois **Lugares**. Escolha como a sala est\xE1 arrumada e arraste cada aluno para uma carteira. Soltar um aluno sobre outro troca os dois de lugar.","help.seating_a2":"**Embaralhar** d\xE1 um novo lugar a todos, com Desfazer. Clique em um aluno e escolha **Manter neste lugar** para quem n\xE3o deve mudar. O menu **⋯** arruma as carteiras, mostra o mapa \xE0 turma e o imprime.","help.seating_a3":"**Sortear um nome**, no cabe\xE7alho da turma, mostra um aluno ao acaso, e ningu\xE9m sai duas vezes at\xE9 todos terem tido a vez. **Formar grupos** divide a turma em grupos; arraste um nome para mov\xEA-lo ou clique em dois nomes para troc\xE1-los. **Montar eu mesmo** come\xE7a com todos os grupos vazios. **Quem est\xE1 aqui** deixa de fora quem faltou hoje. Ctrl Z desfaz um movimento ou um embaralhamento.","help.seating_a4":"Enquanto apresenta uma aula, pressione **P** para sortear um nome e **G** para grupos. Os nomes s\xF3 s\xE3o mostrados: nunca v\xE3o para uma aula nem para a sua pasta do Planejador.","help.seating_w":"mapa de sala lugares carteiras grupos sorteio sortear aleat\xF3rio embaralhar","help.missing_work_q":"Como lembro os estudantes dos trabalhos pendentes?","help.missing_work_a1":"Abra uma turma e escolha a aba **Pend\xEAncias**. Ela lista cada trabalho que voc\xEA marcou como N\xE3o entregue, por aluno ou por atividade, no per\xEDodo que voc\xEA escolher.","help.missing_work_a2":"**Enviar lembrete** abre um e-mail no seu pr\xF3prio aplicativo de e-mail, j\xE1 endere\xE7ado e listando o que o aluno deve. Leia e envie voc\xEA mesmo: o aplicativo n\xE3o envia nada. **E-mail para todos** numa atividade escreve um \xFAnico e-mail com todos os endere\xE7os em Cco.","help.missing_work_a3":"Os e-mails v\xEAm da aba Pessoas. **Texto do e-mail…** muda o que todos os lembretes dizem.","help.missing_work_w":"atrasado pendente n\xE3o entregue deve cobrar e-mail lembrete fam\xEDlias","help.progress_sheet_q":"Posso imprimir uma p\xE1gina sobre um aluno para uma reuni\xE3o de pais?","help.progress_sheet_a1":"Sim. Abra a turma, escolha **Pessoas** e clique em **Fichas de progresso** para uma p\xE1gina por aluno, ou clique num nome e em **Ficha de progresso** para uma s\xF3.","help.progress_sheet_a2":"Cada p\xE1gina tem a nota do per\xEDodo, a m\xE9dia de cada tipo, todas as notas, um gr\xE1fico da evolu\xE7\xE3o, trabalhos n\xE3o entregues, a nota de cada per\xEDodo, o coment\xE1rio do boletim e linhas para anota\xE7\xF5es. Escolha o per\xEDodo no alto e desmarque o que n\xE3o quiser.","help.progress_sheet_a3":"Clique em **Imprimir** e escolha uma impressora ou Salvar como PDF. A p\xE1gina \xE9 feita no seu computador e nada \xE9 enviado a lugar nenhum.","help.progress_sheet_w":"imprimir pais reuni\xE3o respons\xE1veis boletim progresso ficha pdf","help.where_saved_q":"Onde meu trabalho \xE9 salvo?","help.where_saved_a1":"Neste navegador, neste computador, enquanto voc\xEA trabalha. N\xE3o h\xE1 bot\xE3o de salvar nem conta.","help.where_saved_a2":"Um navegador pode ser limpo, ent\xE3o escolha uma pasta como segunda c\xF3pia: Configura\xE7\xF5es, **Salvamento e sincroniza\xE7\xE3o**. At\xE9 l\xE1, as Configura\xE7\xF5es dizem que o seu trabalho est\xE1 s\xF3 neste navegador.","help.where_saved_a3":"No Safari e no Firefox, que n\xE3o conseguem salvar em uma pasta, crie de vez em quando um arquivo para levar.","help.where_saved_w":"salvar c\xF3pia de seguran\xE7a backup pasta armazenamento perdido apagado seguro","help.where_saved_go":"Abrir Salvamento e sincroniza\xE7\xE3o","help.other_computer_q":"Como levo meu trabalho para outro computador?","help.other_computer_a1":"1. Em Configura\xE7\xF5es, **Salvamento e sincroniza\xE7\xE3o**, clique em **Levar meu trabalho comigo**. Isso cria um arquivo protegido por uma frase secreta que voc\xEA escolhe.","help.other_computer_a2":"2. Leve o arquivo para o outro computador.","help.other_computer_a3":"3. L\xE1, clique em **Trazer trabalho**. Ele mostra o que vai mudar antes de mudar qualquer coisa.","help.other_computer_a4":"A volta funciona do mesmo jeito. Se o mesmo aluno mudou nos dois lugares, voc\xEA v\xEA as duas vers\xF5es e escolhe. As suas aulas v\xE3o junto. As aulas que j\xE1 est\xE3o naquele computador ficam, e s\xF3 entram as que ele n\xE3o tem.","help.other_computer_w":"casa notebook transferir levar sincronizar segundo computador usb","help.other_computer_go":"Abrir Salvamento e sincroniza\xE7\xE3o","help.new_address_q":"O aplicativo mudou para um novo endere\xE7o da web. Onde est\xE1 o meu trabalho?","help.new_address_a1":"O seu trabalho \xE9 guardado pelo navegador para o endere\xE7o que voc\xEA abriu, ent\xE3o um endere\xE7o novo come\xE7a vazio. Nada se perdeu: continua no endere\xE7o antigo.","help.new_address_a2":"1. Abra o endere\xE7o antigo. Em Configura\xE7\xF5es, **Salvamento e sincroniza\xE7\xE3o**, clique em **Levar meu trabalho comigo** e salve o arquivo. Ele cont\xE9m o seu trabalho de corre\xE7\xE3o e as suas aulas.","help.new_address_a3":"2. Abra o endere\xE7o novo.","help.new_address_a4":"3. L\xE1, em Configura\xE7\xF5es, **Salvamento e sincroniza\xE7\xE3o**, clique em **Trazer trabalho** e escolha o arquivo.","help.new_address_w":"endere\xE7o url mudou novo site vazio perdido","help.new_address_go":"Abrir Salvamento e sincroniza\xE7\xE3o","help.new_year_q":"Como come\xE7o um novo ano letivo?","help.new_year_a1":"1. Em Configura\xE7\xF5es, **Salvamento e sincroniza\xE7\xE3o**, clique em **Come\xE7ar um novo ano**.","help.new_year_a2":"2. Confira os nomes dos dois anos e o que continua, escolha uma frase secreta e clique em **Salvar o arquivo e come\xE7ar o novo ano**. Este ano vai para um \xFAnico arquivo protegido, e o arquivo \xE9 lido de volta e conferido antes de qualquer coisa ser apagada.","help.new_year_a3":"Suas turmas, unidades e cart\xF5es de atividade ficam, cada cart\xE3o com a sua rubrica e os quadros de Corre\xE7\xE3o r\xE1pida, e as datas avan\xE7am um ano. Listas de turma, trabalhos, notas e coment\xE1rios saem deste navegador e v\xE3o para o arquivo. As unidades avan\xE7am um ano junto com o resto.","help.new_year_a4":"Para ver um ano antigo de novo, clique em **Abrir um ano arquivado** e escolha o arquivo dele. O ano em que voc\xEA est\xE1 \xE9 salvo antes em um arquivo pr\xF3prio, para voc\xEA poder voltar.","help.new_year_w":"novo ano letivo virada arquivar esvaziar listas fim de ano","help.new_year_go":"Abrir Salvamento e sincroniza\xE7\xE3o","help.go_back_q":"Cometi um erro. Posso voltar a como estava?","help.go_back_a1":"Desfazer (Ctrl Z, ou ⌘Z) volta, um passo de cada vez, pelas marcas no trabalho e pelas notas que voc\xEA deu.","help.go_back_a2":"Excluir uma unidade, uma tarefa ou uma turma mostra **Desfazer** por alguns segundos.","help.go_back_a3":"Para algo maior, Configura\xE7\xF5es, **Salvamento e sincroniza\xE7\xE3o**, **Voltar no tempo** lista o seu trabalho como estava em dias anteriores. **Ver** compara antes e agora. **Restaurar esta atividade** traz de volta uma atividade e deixa o resto como est\xE1.","help.go_back_w":"desfazer restaurar hist\xF3rico perdido apagado recuperar c\xF3pia","help.go_back_go":"Abrir Salvamento e sincroniza\xE7\xE3o","help.offline_q":"Funciona sem internet?","help.offline_a1":"Sim. Depois da primeira visita o aplicativo fica no computador e abre sem conex\xE3o. Seu trabalho nunca precisou dela.","help.offline_a2":"Em Configura\xE7\xF5es, **Sobre e atualiza\xE7\xF5es** permite instal\xE1-lo como um aplicativo com janela e \xEDcone pr\xF3prios.","help.offline_w":"offline wifi instalar aplicativo avi\xE3o","help.offline_go":"A","help.updates_q":"Como funcionam as atualiza\xE7\xF5es?","help.updates_a1":"Uma vers\xE3o mais nova \xE9 baixada em sil\xEAncio, e Configura\xE7\xF5es, **Sobre e atualiza\xE7\xF5es** avisa que ela est\xE1 pronta. Nada muda at\xE9 voc\xEA clicar em **Atualizar agora**, que salva o seu trabalho antes.","help.updates_a2":"Uma atualiza\xE7\xE3o nunca chega no meio de uma corre\xE7\xE3o.","help.updates_w":"vers\xE3o nova atualizar novidades mudan\xE7as","help.updates_go":"A","help.planner_q":"Onde est\xE1 o Planejador agora?","help.planner_a1":"O planejamento agora faz parte do aplicativo. Cada turma tem uma **Linha do curso** com suas unidades e aulas por semana, o **Calend\xE1rio** mostra todas as turmas por semana, por hor\xE1rio ou por m\xEAs, e cada aula tem o seu plano, os seus slides e um editor de slides que cria arquivos do PowerPoint. O banco de atividades e o banco de rubricas ficam na **Biblioteca**.","help.planner_a2":"As aulas nunca guardam trabalho de corre\xE7\xE3o: trabalhos, nomes e notas dos alunos ficam do lado da corre\xE7\xE3o.","help.planner_w":"aulas unidades calend\xE1rio slides planejar powerpoint","help.planner_go":"Abrir o Calend\xE1rio","help.timetable_q":"Como configuro meu hor\xE1rio?","help.timetable_a1":"Em Configura\xE7\xF5es, **Hor\xE1rio**, digite as suas turmas, quando cada uma se re\xFAne e os dias em que a escola est\xE1 fechada. **Salvar meu arquivo de configura\xE7\xE3o** guarda tudo, incluindo o seu modelo de slides, num arquivo que voc\xEA pode carregar em outro computador.","help.timetable_a2":"O In\xEDcio e o Calend\xE1rio passam a mostrar as turmas que voc\xEA tem em cada dia, com a aula planejada para cada uma.","help.timetable_w":"hor\xE1rio per\xEDodos turmas horas calend\xE1rio feriados","help.timetable_go":"Abrir Hor\xE1rio","help.present_q":"Como apresento uma aula para a turma?","help.present_a1":"Abra a aula e clique em **Apresentar**. Os slides ocupam a tela; as setas do teclado ou um passador de slides avan\xE7am por eles. No In\xEDcio, a pr\xF3xima turma tem o seu pr\xF3prio bot\xE3o **Apresentar**.","help.present_a2":"Durante a apresenta\xE7\xE3o: **A** mostra a pauta, **T** inicia um cron\xF4metro que a turma v\xEA, **P** sorteia um aluno, **G** forma grupos, **N** mostra suas notas, **B** deixa a tela em branco, **W** abre os slides numa janela separada para uma segunda tela ou projetor, e **Esc** encerra.","help.present_a3":"O cron\xF4metro aceita minutos e segundos. Enquanto ele roda, o menu dele acrescenta ou tira 10 segundos ou um minuto, pausa e reinicia; **+** e **−** acrescentam ou tiram um minuto. Marque **Show it big** para p\xF4r a contagem no meio da tela, para o fundo da sala.","help.present_a4":"O cron\xF4metro continua depois que voc\xEA termina ou sai da tela cheia: ele espera no canto. Depois, uma linha anota at\xE9 onde a turma chegou, e ao apresentar de novo voc\xEA continua dali.","help.present_w":"apresenta\xE7\xE3o tela cheia projetor ensinar cron\xF4metro roteiro controle","help.pptx_q":"Posso obter meus slides como arquivo do PowerPoint?","help.pptx_a1":"Sim. Abra a aula e escolha **PowerPoint final** no menu ao lado dos slides. O arquivo abre no PowerPoint, no Keynote e no Google Slides.","help.pptx_a2":"Os slides usam um modelo branco simples, a n\xE3o ser que voc\xEA forne\xE7a o seu: em Configura\xE7\xF5es, **Hor\xE1rio**, clique em **Usar o modelo da minha escola…** e escolha um arquivo do PowerPoint com um layout Slide de t\xEDtulo e um layout T\xEDtulo e conte\xFAdo.","help.pptx_w":"powerpoint pptx exportar slides keynote google slides baixar","help.sharelesson_q":"Como levo uma aula para outro computador ou a passo para outro professor?","help.sharelesson_a1":"Abra a aula e escolha **Compartilhar arquivo da aula…** nas ferramentas dela. Voc\xEA recebe um arquivo pequeno com os slides, as anota\xE7\xF5es, as imagens, os materiais e o PowerPoint final, se houver.","help.sharelesson_a2":"No outro computador, clique em **Importar uma aula** na Biblioteca, ou solte o arquivo na Biblioteca. Em quais turmas e dias ela estava, as anota\xE7\xF5es das aulas dadas e os coment\xE1rios para o seu assistente de IA ficam de fora.","help.sharelesson_w":"compartilhar aula arquivo exportar importar colega outro computador","help.sharelesson_go":"Abrir a Biblioteca","help.privacy_q":"Os trabalhos dos alunos saem do meu computador?","help.privacy_a1":"N\xE3o. Os trabalhos, os nomes, as notas e os coment\xE1rios ficam neste navegador e na pasta que voc\xEA escolher. O aplicativo n\xE3o tem servidor nem contas, e funciona sem internet.","help.privacy_a2":"S\xF3 saem os arquivos que voc\xEA mesmo exporta.","help.privacy_a3":"Uma vez por dia, o aplicativo no seu endere\xE7o da web soma um a uma contagem p\xFAblica de quantos navegadores o abriram, para que quem o criou saiba se algu\xE9m o usa. Nada sobre voc\xEA, seus alunos ou seu trabalho \xE9 enviado.","help.privacy_w":"privado prote\xE7\xE3o de dados lgpd nuvem servidor seguro","help.ai_q":"O aplicativo usa IA nos trabalhos dos alunos?","help.ai_a1":"N\xE3o. Nada no aplicativo envia trabalhos de alunos a uma IA, e s\xF3 voc\xEA d\xE1 as notas.","help.ai_a2":"Compartilhar com um assistente de IA, na aba Return, \xE9 opcional e fica desligado at\xE9 voc\xEA usar. Cria uma c\xF3pia sem nomes: cada aluno recebe um c\xF3digo aleat\xF3rio, os nomes digitados s\xE3o cobertos e a chave fica no seu navegador.","help.ai_w":"intelig\xEAncia artificial ia claude chatgpt corre\xE7\xE3o autom\xE1tica m\xE1quina","help.ai_go":"A","help.remove_q":"Como removo os trabalhos dos alunos deste computador?","help.remove_a1":"Em Configura\xE7\xF5es, **Salvamento e sincroniza\xE7\xE3o**, **Remover deste computador** apaga todos os trabalhos dos alunos deste navegador depois que voc\xEA digita REMOVER.","help.remove_a2":"Ele nunca apaga o que est\xE1 na sua pasta vinculada. Ele avisa, deixa de usar a pasta e deixa os arquivos com voc\xEA.","help.remove_w":"apagar excluir limpar fim de ano computador compartilhado","help.remove_go":"Abrir Salvamento e sincroniza\xE7\xE3o","help.title":"Ajuda","help.about":"Todas as respostas, e onde cada coisa fica agora.","help.find":"Buscar na ajuda","help.n_answers":{"one":"{n} resposta","other":"{n} respostas"},"help.none":"Nenhuma resposta corresponde a “{q}”. Tente menos palavras, ou use Buscar.","help.map":"Onde cada coisa fica","help.map_about":"Tudo o que o app fazia antes, e onde est\xE1 agora.","help.go":"Ir","help.keys":"Atalhos de teclado","help.new":"Novidades","help.new_about":"As mudan\xE7as de cada vers\xE3o, em palavras simples.","help.new_more":"Mostrar vers\xF5es anteriores","help.version":"Vers\xE3o {v}","help.cmd_group":"Ajuda","help.mg_day":"Todo dia","help.mf_home":"Hoje: o que vem a seguir, por turma","help.mw_home":"In\xEDcio","help.mf_week":"A semana de todas as turmas","help.mw_week":"Calend\xE1rio, Por turma; Esta semana no In\xEDcio","help.mf_bytime":"A semana hora a hora, com aulas e pend\xEAncias para arrastar","help.mw_bytime":"Calend\xE1rio, Por hor\xE1rio","help.mf_month":"O m\xEAs: unidades, feriados, eventos da escola","help.mw_month":"Calend\xE1rio, M\xEAs","help.mf_todo":"Pend\xEAncias: as suas e as do app","help.mw_todo":"Pend\xEAncias, e a aba Pend\xEAncias de cada turma","help.mf_focus":"Cron\xF4metro de foco, sess\xF5es, m\xFAsica lo-fi","help.mw_focus":"Pend\xEAncias, Foco; o bot\xE3o de foco no In\xEDcio","help.mf_time":"Registro de tempo","help.mw_time":"Pend\xEAncias, Tempo nesta semana","help.mf_gplan":"Plano de corre\xE7\xE3o","help.mw_gplan":"Pend\xEAncias, Plano de corre\xE7\xE3o","help.mg_plan":"Planejamento","help.mf_course":"Planeje aulas por semana a partir do seu hor\xE1rio","help.mw_course":"Uma turma, Linha do curso","help.mf_lesson":"Uma aula como um s\xF3 plano, seus slides e o editor de slides","help.mw_lesson":"Uma aula: Aula, Slides, Editar","help.mf_present":"Modo de apresenta\xE7\xE3o","help.mw_present":"Uma aula, Apresentar; In\xEDcio","help.mf_banks":"Aulas anteriores, o banco de atividades, o banco de rubricas","help.mw_banks":"Biblioteca","help.mf_timetable":"Hor\xE1rio e o modelo de slides","help.mw_timetable":"Configura\xE7\xF5es, Hor\xE1rio","help.mg_cls":"Turmas","help.mf_work":"Atividades por unidade","help.mw_work":"Uma turma, Atividades e Linha do curso","help.mf_grades":"Gradebook, charts, learning goals,: coment\xE1rios de boletim","help.mw_grades":"Uma turma, Notas","help.mf_people":"Alunos, a p\xE1gina de cada aluno, fichas de progresso, lista de acompanhamento","help.mw_people":"Uma turma, Pessoas","help.mf_seat":"Frequ\xEAncia, lugares, grupos, sortear um nome","help.mw_seat":"Uma turma, Pessoas; Sortear um nome no cabe\xE7alho da turma","help.mf_examples":"Bons exemplos","help.mw_examples":"Biblioteca, Exemplos","help.mg_asg":"Uma atividade","help.mf_mark":"Corrigir trabalhos: caneta, coment\xE1rios, carimbos, rubrica, anota\xE7\xF5es digitadas, parceiros","help.mw_mark":"Uma atividade, Corrigir","help.mf_out":"Planilha de notas, an\xE1lise, devolver e exportar","help.mw_out":"Corre\xE7\xE3o: Notas, An\xE1lise, Devolver","help.mf_in":"Trazer trabalhos: ZIP, pasta, digitaliza\xE7\xE3o, Google Drive","help.mw_in":"Uma atividade, Trazer trabalhos","help.mg_else":"Todo o resto","help.mf_school":"Links, arquivos, anota\xE7\xF5es e pessoas da sua escola","help.mw_school":"Escola","help.mf_find":"Buscar","help.mw_find":"Ctrl K, ou a caixa no topo da barra lateral","help.mf_setup":"Seu assistente, o link dele e a importa\xE7\xE3o da configura\xE7\xE3o","help.mw_setup":"Configura\xE7\xF5es, Trabalhar com IA; Configura\xE7\xF5es, Turmas e per\xEDodos, Minha configura\xE7\xE3o","help.mf_saving":"Google Drive, a pasta de backup, o arquivo para levar para casa, voltar no tempo","help.mw_saving":"Configura\xE7\xF5es, Salvamento e sincroniza\xE7\xE3o","help.mf_look":"Temas, idioma, a turma de exemplo","help.mw_look":"Configura\xE7\xF5es, Exibi\xE7\xE3o","help.mf_keys":"Atalhos de teclado","help.mw_keys":"Ajuda, Atalhos de teclado; ? em qualquer tela","help.cmd_asg":"Atividades","help.cmd_pages":"P\xE1ginas da turma","help.cmd_p_work":"{name}: atividades","help.cmd_p_people":"{name}: pessoas","help.cmd_p_grades":"{name}: notas","help.cmd_p_todo":"{name}: pend\xEAncias","help.cmd_no_class":"Sem turma","help.cmd_open_work":"Abrir trabalhos dos alunos","help.cmd_open_folder":"Abrir uma pasta de trabalhos","help.cmd_split":"Separar uma digitaliza\xE7\xE3o com os trabalhos de todos","help.cmd_match":"Associar arquivos a uma lista","help.cmd_add_class":"Adicionar uma turma","help.cmd_gc":"Trazer uma turma do Google Classroom","help.cmd_sample":"Experimente com uma turma de exemplo","help.cmd_leave_sample":"Sair do exemplo","help.cmd_new_asg":"Nova atividade","help.cmd_a_download":"Um download","help.cmd_kept":"Guardado neste navegador","help.cmd_todo_week":"Tarefas, por semana","help.cmd_examples":"Exemplos","help.cmd_dark":"Modo escuro","help.cmd_light":"Modo claro","help.cmd_snip":"Captura de tela","help.cmd_snip_also":"Arraste sobre uma parte da tela para copiar uma imagem dela","help.cmd_beside":"Abrir {name} ao lado do Grading Studio","help.cmd_beside_generic":"Abrir seu assistente de IA ao lado do Grading Studio","help.cmd_p_att":"{name}: frequ\xEAncia","help.cmd_p_seat":"{name}: mapa de lugares","help.cmd_p_charts":"{name}: gr\xE1ficos","help.cmd_p_goals":"{name}: metas","help.cmd_p_reports":"{name}: coment\xE1rios do boletim","help.cmd_p_missing":"{name}: trabalhos pendentes"}');export{o as default};
